<body>
<main>
<header><div class="brand"><div class="logo">◉</div><div>OnTrack <span style="color:#fb536b">Voice Lab</span><br><small>تجربة مستقلة — Gemini 3.8 Live</small></div></div><div class="badge">Egyptian Arabic • Demo</div></header>
<section class="panel hero">
<h1>كلم المساعد بالمصري</h1>
<p class="help" id="buildInfo">Voice Lab 2026.11.07.4 • Gemini 3.8 Live — صوت مباشر</p>
<p>Gemini 3.8 Live يسمعك ويرد عليك بصوته مباشرة • نص وصوت من نفس الموديل</p>
<button id="mic" class="orb" aria-label="ابدأ مكالمة صوتية">🎙</button>
<div id="status" class="status" role="status">جاهز للمكالمة</div>
<div class="actions"><button id="stop" class="ghost" type="button">إنهاء المكالمة</button><button id="testVoice" class="ghost" type="button">تجربة الصوت فقط</button></div>
<div class="timing"><span id="brainTime">Gemini: —</span><span id="firstAudio">أول صوت: —</span><span id="totalTime">إجمالي: —</span></div>
</section>
<section class="panel"><h2>المحادثة</h2><div id="log" aria-live="polite"><p class="muted">ابدأ بالمايك أو اكتب رسالة. هتظهر هنا الجمل والردود.</p></div><form id="textForm" class="send"><input id="textInput" type="text" autocomplete="off" placeholder="اكتب حاجة بالمصري لو المايك مش متاح..." aria-label="رسالتك"><button type="submit">إرسال</button></form></section>
<section class="panel"><details open><summary>⚙️ إعدادات التجربة</summary>
<div class="grid">
<label>الموديل الأساسي <input type="text" value="Gemini 3.8 Live — صوت ومحادثة مباشرة" readonly></label>
<label>Google Gemini API Key<input id="googleKey" type="password" autocomplete="new-password" placeholder="مفتاح جديد أو سيبه فاضي لاستخدام المحفوظ"><span id="googleSaved" class="settings-note">جارٍ تحميل حالة المفتاح...</span></label>
<label>مستوى المشاعر<select id="emotionLevel"><option value="intense">جياشة — تنهيدات وتعبير واضح</option><option value="expressive">معبرة — طبيعية ومتغيرة</option><option value="subtle">هادية — لمسات خفيفة</option></select></label>
<label>إيقاف الاستماع بعد كل رد<select id="autoListen"><option value="no">لا — كمّل مكالمة تلقائيًا</option><option value="yes">نعم — اضغط المايك لكل جملة</option></select></label>
</div>
<label class="inline"><input id="emotions" type="checkbox" checked> صوت مصري بمشاعر وتنهدات طبيعية من Gemini Live</label>
<div class="settings-actions"><button type="button" id="saveSettings">💾 حفظ المفتاح والإعدادات</button><span id="settingsStatus" class="settings-state" role="status" aria-live="polite">المفتاح بيتحفظ مشفر على السيرفر.</span></div>
<label class="inline"><input id="removeGoogle" type="checkbox"> حذف مفتاح Google المحفوظ عند الحفظ</label>
<p class="help">Gemini 3.8 Live هو الموديل الوحيد للمحادثة والصوت؛ المايك بيتبعت مباشرة عبر WebSocket بتوكن قصير الصلاحية، وصوت الرد بيتشغّل فور وصوله. تقدر تحفظ مفتاح Google مرة واحدة وتستخدمه بعد كده بدون كتابته تاني. يلزم تسجيل دخول أدمن OnTrack. الصوت مباشر من Gemini، بدون Flash أو Puter أو Fish TTS.</p>
</details></section>
<audio id="player" playsinline></audio>
</main>
<script>

(function () {
  'use strict';
  const el = id => document.getElementById(id);
  const ui = {
    mic:el('mic'), stop:el('stop'), test:el('testVoice'), status:el('status'), log:el('log'),
    textForm:el('textForm'), textInput:el('textInput'),
    googleKey:el('googleKey'), googleSaved:el('googleSaved'),
    emotionLevel:el('emotionLevel'), autoListen:el('autoListen'), emotions:el('emotions'),
    save:el('saveSettings'), settingsStatus:el('settingsStatus'), removeGoogle:el('removeGoogle'),
    brain:el('brainTime'), first:el('firstAudio'), total:el('totalTime')
  };
  let csrf='',savedGoogle=false,live=null,active=false,starting=false,tokenAbort=null;
  let settingsReady=Promise.resolve();
  const AudioCtx=window.AudioContext||window.webkitAudioContext;
  function status(message){ui.status.textContent=message;}
  function message(role,text){
    if(!text)return;
    const item=document.createElement('div');
    item.className='bubble '+(role==='user'?'mine':'theirs');
    item.textContent=(role==='user'?'أنت: ':'المساعدة: ')+text;
    ui.log.appendChild(item);
    ui.log.scrollTop=ui.log.scrollHeight;
  }
  function keyLabel(){
    ui.googleSaved.textContent=savedGoogle?'✓ مفتاح Google محفوظ مشفر على السيرفر':'لم يتم حفظ مفتاح Google';
  }
  async function loadSettings(){
    const response=await fetch('./settings.php',{credentials:'same-origin',cache:'no-store'});
    if(!response.ok)throw Error(response.status===401?'سجّل دخولك كأدمن OnTrack':'تعذّر تحميل الإعدادات HTTP '+response.status);
    const result=await response.json();
    if(!result.ok||!result.csrf)throw Error('رد السيرفر غير صالح');
    csrf=result.csrf;
    for(const name of ['emotionLevel','autoListen']){
      const value=result.settings?.[name];
      if(typeof value==='string'&&Array.from(ui[name].options).some(option=>option.value===value))ui[name].value=value;
    }
    if(typeof result.settings?.emotions==='boolean')ui.emotions.checked=result.settings.emotions;
    savedGoogle=!!result.saved?.google;keyLabel();
    ui.settingsStatus.textContent='الإعدادات اتحمّلت. سيب حقل المفتاح فاضي لاستخدام المحفوظ.';
  }
  async function secureHeaders(){
    await settingsReady;
    if(!csrf)throw Error('لازم تكون داخل بحساب أدمن OnTrack');
    const headers={'Content-Type':'application/json','X-Voice-Lab-CSRF':csrf};
    if(ui.googleKey.value.trim())headers['X-Gemini-API-Key']=ui.googleKey.value.trim();
    return headers;
  }
  function instructions(){
    const mood=ui.emotionLevel.value;
    const emotion=ui.emotions.checked
      ? mood==='intense'?'عبّري عن المشاعر بوضوح، مع تنهيدات وضحكات وهمسات مناسبة من غير مبالغة.'
      : mood==='subtle'?'مشاعر هادية وطبيعية وتغيير بسيط في النبرة.'
      :'كوني ودودة ومرحة، بنبرة معبرة تتغير طبيعيًا حسب الكلام.'
      :'اتكلمي بطبيعية وبلا تعليمات أداء.';
    return 'إنتِ بنت مصرية بتتكلمي بالمصري بطلاقة وعفوية. استمعي للمستخدم للآخر بدون مقاطعة، وردّي بصوت طبيعي وواضح وباختصار، من غير تقديم رسمي أو حشو. ردي بالصوت المصري وليس بلغة أخرى. '+emotion;
  }
  function stopLive(){
    if(tokenAbort){tokenAbort.abort();tokenAbort=null;}
    const s=live;live=null;
    if(!s)return;
    s.closed=true;
    clearTimeout(s.handshakeTimer);
    if(s.node){s.node.onaudioprocess=null;try{s.node.disconnect();}catch(e){}}
    for(const source of s.playing){try{source.stop();}catch(e){}}
    s.playing.clear();
    if(s.silence)try{s.silence.disconnect();}catch(e){}
    if(s.source)try{s.source.disconnect();}catch(e){}
    if(s.media)for(const track of s.media.getTracks())track.stop();
    if(s.inputContext)s.inputContext.close().catch(()=>{});
    if(s.playback)s.playback.close().catch(()=>{});
    if(s.socket&&s.socket.readyState<=1)try{s.socket.close(1000,'stop');}catch(e){}
  }
  function reset(){
    active=false;starting=false;stopLive();
    ui.mic.classList.remove('active');ui.mic.textContent='🎙';
    status('تم إنهاء المكالمة');
  }
  function appendText(existing,chunk){
    const text=String(chunk||'').trim();
    if(!text||text===existing||existing.endsWith(text))return existing;
    if(!existing||text.startsWith(existing))return text;
    return existing+' '+text;
  }
  function pcm16Base64(samples,sampleRate){
    const length=Math.max(1,Math.floor(samples.length*16000/sampleRate));
    const bytes=new Uint8Array(length*2), view=new DataView(bytes.buffer);
    for(let i=0;i<length;i++){
      const value=Math.max(-1,Math.min(1,samples[Math.min(samples.length-1,Math.floor(i*sampleRate/16000))]||0));
      view.setInt16(i*2,value<0?value*32768:value*32767,true);
    }
    let binary='';for(let i=0;i<bytes.length;i++)binary+=String.fromCharCode(bytes[i]);
    return btoa(binary);
  }
  async function startMic(s){
    if(!navigator.mediaDevices?.getUserMedia)throw Error('المايك يحتاج HTTPS ومتصفح حديث');
    status('اسمح للمتصفح بالمايك...');
    s.media=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});
    if(live!==s||s.closed){s.media.getTracks().forEach(track=>track.stop());return;}
    s.inputContext=new AudioCtx();
    s.source=s.inputContext.createMediaStreamSource(s.media);
    s.node=s.inputContext.createScriptProcessor(2048,1,1);
    s.silence=s.inputContext.createGain();s.silence.gain.value=0;
    s.node.onaudioprocess=event=>{
      if(live!==s||s.closed||!s.ready||s.speaking||s.socket.readyState!==WebSocket.OPEN||s.socket.bufferedAmount>500000)return;
      s.socket.send(JSON.stringify({realtimeInput:{audio:{mimeType:'audio/pcm;rate=16000',data:pcm16Base64(event.inputBuffer.getChannelData(0),s.inputContext.sampleRate)}}}));
    };
    s.source.connect(s.node);s.node.connect(s.silence);s.silence.connect(s.inputContext.destination);
    await s.inputContext.resume();
    status('Gemini 3.8 Live بيسمعك...');
  }
  function sendText(s,text){
    if(!s.ready){s.pending.push(text);return;}
    message('user',text);
    s.turnStart=performance.now();ui.first.textContent='أول صوت: ...';
    s.socket.send(JSON.stringify({realtimeInput:{text}}));
    status('Gemini 3.8 Live بيرد بالصوت...');
  }
  function playChunk(s,base64){
    if(live!==s||s.closed)return;
    const binary=atob(base64);
    if(binary.length<2)return;
    const count=Math.floor(binary.length/2),pcm=new Float32Array(count),bytes=new DataView(new ArrayBuffer(count*2));
    for(let i=0;i<count*2;i++)bytes.setUint8(i,binary.charCodeAt(i));
    for(let i=0;i<count;i++)pcm[i]=bytes.getInt16(i*2,true)/32768;
    const buffer=s.playback.createBuffer(1,count,24000);
    buffer.copyToChannel(pcm,0);
    const source=s.playback.createBufferSource();
    source.buffer=buffer;source.connect(s.playback.destination);
    const startAt=Math.max(s.playback.currentTime+0.03,s.nextAudioAt||0);
    s.nextAudioAt=startAt+buffer.duration;
    s.playing.add(source);
    source.onended=()=>s.playing.delete(source);
    source.start(startAt);
    s.speaking=true;
    if(!s.firstAudio){
      s.firstAudio=true;
      ui.first.textContent='أول صوت: '+Math.round(performance.now()-(s.turnStart||s.connectedAt))+'ms';
      ui.brain.textContent='Gemini 3.8 Live — صوت مباشر';
    }
    status('Gemini 3.8 Live بيتكلم...');
  }
  async function finishTurn(s){
    if(live!==s||s.closed)return;
    const heard=s.input.trim(),spoken=s.output.trim();
    s.input='';s.output='';
    if(heard)message('user',heard);
    if(spoken)message('assistant',spoken);
    const remaining=Math.max(0,(s.nextAudioAt-s.playback.currentTime)*1000);
    if(remaining>0)await new Promise(resolve=>setTimeout(resolve,Math.min(remaining+80,45000)));
    if(live!==s||s.closed)return;
    s.speaking=false;s.firstAudio=false;s.nextAudioAt=0;
    ui.total.textContent='زمن الرد: '+Math.round(performance.now()-(s.turnStart||s.connectedAt))+'ms';
    if(ui.autoListen.value==='yes'&&s.withMic){
      reset();status('جاهز للجملة التالية — اضغط المايك');return;
    }
    status(s.withMic?'Gemini 3.8 Live بيسمعك...':'تقدر تبعت رسالة تانية');
  }
  function receive(s,raw){
    let result;try{result=JSON.parse(raw);}catch(e){return;}
    if(result.error){
      const detail=String(result.error.message||result.error.status||result.error.code||'خطأ غير محدد').replace(/AIza[A-Za-z0-9_-]+/g,'[redacted]').slice(0,280);
      reset();status('Google رفض جلسة Live: '+detail);return;
    }
    if(result.setupComplete){
      clearTimeout(s.handshakeTimer);s.ready=true;s.connectedAt=performance.now();
      status('اتصلنا بـGemini 3.8 Live');
      if(s.withMic)startMic(s).catch(e=>{reset();status('مشكلة المايك: '+e.message);});
      for(const text of s.pending.splice(0))sendText(s,text);
      return;
    }
    const content=result.serverContent||{};
    if(content.inputTranscription?.text)s.input=appendText(s.input,content.inputTranscription.text);
    if(content.outputTranscription?.text)s.output=appendText(s.output,content.outputTranscription.text);
    for(const part of content.modelTurn?.parts||[]){
      const pcm=part.inlineData;
      if(pcm?.data&&String(pcm.mimeType||'').startsWith('audio/pcm')){
        try{playChunk(s,pcm.data);}catch(e){status('تعذّر تشغيل صوت Gemini: '+e.message);}
      }
    }
    if(content.interrupted){
      for(const source of s.playing)try{source.stop();}catch(e){}
      s.playing.clear();s.nextAudioAt=0;s.output='';s.speaking=false;s.firstAudio=false;
    }
    if(content.turnComplete){
      s.queue=s.queue.then(()=>finishTurn(s)).catch(e=>status('Gemini Live: '+e.message));
    }
  }
  async function startLive(firstText=null){
    if(live){if(firstText)sendText(live,firstText);return;}
    if(starting)return;
    if(!window.WebSocket||!AudioCtx)throw Error('متصفحك لا يدعم مكالمات Live');
    starting=true;
    // Start playback inside the user's click to satisfy mobile autoplay policies.
    const playback=new AudioCtx({sampleRate:24000});
    const resumePlayback=playback.resume();
    let attached=false;
    try{
      const headers=await secureHeaders();
      await resumePlayback;
      const abort=new AbortController();tokenAbort=abort;
      const timeout=setTimeout(()=>abort.abort(),18000);
      let response;
      try{response=await fetch('./live-token.php',{method:'POST',headers,credentials:'same-origin',body:'{}',cache:'no-store',signal:abort.signal});}
      catch(e){throw Error(e.name==='AbortError'?'طلب توكن Live انتهت مهلته':e.message);}
      finally{clearTimeout(timeout);if(tokenAbort===abort)tokenAbort=null;}
      if(!response.ok){
        const detail=(await response.text()).slice(0,350);
        throw Error('التوكن HTTP '+response.status+': '+detail);
      }
      const data=await response.json();
      if(!data.token)throw Error('Google لم يرجع توكن Live');
      if(!active)return;
      const s={socket:null,closed:false,ready:false,withMic:!firstText,pending:firstText?[firstText]:[],
        input:'',output:'',playback,inputContext:null,source:null,node:null,silence:null,media:null,playing:new Set(),
        speaking:false,firstAudio:false,nextAudioAt:0,queue:Promise.resolve(),turnStart:performance.now(),connectedAt:performance.now()};
      live=s;attached=true;
      const endpoint='wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContentConstrained?access_token='+encodeURIComponent(data.token);
      const socket=new WebSocket(endpoint);s.socket=socket;
      s.handshakeTimer=setTimeout(()=>{
        if(live!==s||s.closed||s.ready)return;
        const phase=s.socketOpened?'الـWebSocket اتفتح لكن Google ما أكملش قبول إعدادات الجلسة':'الـWebSocket ما اتفتحش';
        reset();status(phase+' خلال 15 ثانية.');
      },15000);
      socket.onopen=()=>{
        if(live!==s||s.closed)return;
        s.socketOpened=true;status('WebSocket اتفتح؛ مستني قبول Gemini 3.8 Live...');
        socket.send(JSON.stringify({setup:{
          model:'models/gemini-3.8-live',
          generationConfig:{responseModalities:['AUDIO']},
          inputAudioTranscription:{},outputAudioTranscription:{},
          systemInstruction:{parts:[{text:instructions()}]}
        }}));
      };
      socket.onmessage=e=>receive(s,e.data);
      socket.onerror=()=>{if(live!==s||s.closed)return;status('فشل اتصال WebSocket مع Google؛ منتظر كود الإغلاق...');};
      socket.onclose=e=>{if(live!==s||s.closed)return;
        const code=e.code,reason=String(e.reason||'').replace(/AIza[A-Za-z0-9_-]+/g,'[redacted]').slice(0,180);
        reset();status('Google قفل جلسة Live (WebSocket '+code+')'+(reason?': '+reason:'؛ راجع دعم Live للمفتاح والشبكة'));};
      status('بفتح Gemini 3.8 Live...');
    }finally{
      starting=false;
      if(!attached)playback.close().catch(()=>{});
    }
